import pandas as pd
import numpy as np
from scipy.stats import binomtest

df = pd.read_csv('input_file_0.csv')

VARIANTS = ["LAeq", "nospeech_LAeq", "core_LAeq", "top25_LAeq", "L10", "LAeq_1s_mean", "LAeq_limiter_ub"]
MIN_DB = 1.0

paired_trips = []
for trip, group in df.groupby('trip', sort=False):
    dirs = group['direction'].unique()
    if len(dirs) != 1:
        continue
    d = dirs[0]
    if d == 'EB':
        r1 = group[(group['from'] == 'LST') & (group['to'] == 'BTH')]
        r2 = group[(group['from'] == 'BTH') & (group['to'] == 'MLE')]
    elif d == 'WB':
        r1 = group[(group['from'] == 'BTH') & (group['to'] == 'LST')]
        r2 = group[(group['from'] == 'MLE') & (group['to'] == 'BTH')]
    else:
        continue

    if len(r1) == 1 and len(r2) == 1:
        excl = bool(r1['placement_excluded'].iloc[0]) or bool(r2['placement_excluded'].iloc[0])
        diffs = {v: float(r1[v].iloc[0] - r2[v].iloc[0]) for v in VARIANTS}
        paired_trips.append({'trip': trip, 'excluded': excl, **diffs})

pdf = pd.DataFrame(paired_trips)
pok = pdf[~pdf['excluded']]

n = len(pok)
summary = {"n": n}
for v in VARIANTS:
    vals = pok[v]
    n_pos = int((vals > 0).sum())
    summary[v] = {
        "n_positive": n_pos,
        "mean_db": float(vals.mean()),
        "sd_db": float(vals.std(ddof=1)),
        "min_db": float(vals.min()),
        "max_db": float(vals.max()),
        "sign_test_p_one_sided": float(binomtest(n_pos, n, 0.5, alternative="greater").pvalue)
    }

P = {"summary": {"placement_ok": summary}}

s = P["summary"]["placement_ok"]
n, la = s["n"], s["LAeq"]
consistent = la["n_positive"] == n
robust = {k: s[k]["n_positive"] == n for k in VARIANTS}
if consistent and la["mean_db"] >= MIN_DB and all(robust.values()):
    v_str = "GO"
elif consistent:
    v_str = "WEAK"
else:
    v_str = "NO-GO"

print(f"n = {n}")
print(f"verdict = {v_str}")
for v in VARIANTS:
    print(f"n_positive:{v} = {s[v]['n_positive']}")
    print(f"all_trips_positive:{v} = {'true' if robust[v] else 'false'}")

